import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadPlayfair = makeLoadFont('PlayfairDisplay');

// Library: none — native interpolate/spring for layout choreography and SVG drawing

const { fontFamily: interFamily } = loadInter();
const { fontFamily: playfairFamily } = loadPlayfair();



export type FormulaTemplateProps = Record<string, any>;

const FormulaTemplate: React.FC<FormulaTemplateProps> = ({
  backgroundColor = "#050814",
  transparentBackground = false,
  durationInSeconds = 6,
  leftCardTitle = "SCRATCH",
  rightCardTitle1 = "FORMULA",
  rightCardTitle2 = "TEMPLATE",
  pulseColor = "#B4FF00",
  templateItems = [
    { label: "METRIC", value: "SUM ( Revenue )", isResult: false },
    { label: "TIME", value: "This Month", isResult: false },
    { label: "SEGMENT", value: "All Customers", isResult: false },
    { label: "FILTER", value: "Status = Active", isResult: false },
    { label: "", value: "= RESULT", isResult: true },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout Metrics
  const initialCardWidth = width * 0.42;
  const cardHeight = height * 0.85;
  const gap = width * 0.05;
  const margin = (width - initialCardWidth * 2 - gap) / 2;
  const cardTop = (height - cardHeight) / 2;

  const leftCardInitialX = margin;
  const rightCardInitialX = margin + initialCardWidth + gap;

  // Animation Timings
  const entranceSpring = spring({
    frame,
    fps,
    config: { damping: 14, mass: 0.8 },
  });

  const cursorBlink = frame > 15 && frame < 45 && Math.floor(frame / 10) % 2 === 0 ? 1 : 0;

  const xDraw1Progress = interpolate(frame, [40, 50], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const xDraw2Progress = interpolate(frame, [50, 60], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const pulseProgress = interpolate(frame, [70, 80, 95], [0, 1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const fillFrameProgress = spring({
    frame: Math.max(0, frame - 100),
    fps,
    config: { damping: 16, mass: 1 },
  });

  // Entrance Values
  const masterOpacity = interpolate(entranceSpring, [0, 0.5], [0, 1], {
    extrapolateRight: "clamp",
  });
  const masterYOffset = interpolate(entranceSpring, [0, 1], [50 * s, 0]);

  // Fill Frame Layout Values
  const targetRightCardWidth = width * 0.85;
  const targetRightCardX = (width - targetRightCardWidth) / 2;

  const currentRightCardWidth = interpolate(
    fillFrameProgress,
    [0, 1],
    [initialCardWidth, targetRightCardWidth]
  );
  const currentRightCardX = interpolate(
    fillFrameProgress,
    [0, 1],
    [rightCardInitialX, targetRightCardX]
  );

  const leftCardOpacity = interpolate(fillFrameProgress, [0, 0.5], [1, 0], {
    extrapolateRight: "clamp",
  });
  const currentLeftCardX = interpolate(
    fillFrameProgress,
    [0, 1],
    [leftCardInitialX, leftCardInitialX - 100 * s]
  );

  // SVG Drawing Math for Red X
  const xPadding = 40 * s;
  const xAreaWidth = initialCardWidth - xPadding * 2;
  const xAreaHeight = cardHeight * 0.6 - xPadding * 2; // Bottom portion
  const pathLength = Math.sqrt(xAreaWidth * xAreaWidth + xAreaHeight * xAreaHeight);

  // Glow Math
  const baseGlowSize = interpolate(fillFrameProgress, [0, 1], [15 * s, 30 * s]);
  const pulseGlowSize = pulseProgress * 40 * s;
  const totalGlowSize = baseGlowSize + pulseGlowSize;
  const glowOpacity = 0.2 + pulseProgress * 0.6;
  const boxShadow = `0 0 ${totalGlowSize}px rgba(180, 255, 0, ${glowOpacity})`;

  // Pre-entrance safety
  if (frame === 0 && entranceSpring === 0) {
    return <AbsoluteFill style={{ backgroundColor: bgColor }} />;
  }

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      <AbsoluteFill
        style={{
          opacity: masterOpacity,
          transform: `translateY(${masterYOffset}px)`,
          transition: "none",
        }}
      >
        {/* LEFT CARD (SCRATCH) */}
        <div
          style={{
            position: "absolute",
            left: currentLeftCardX,
            top: cardTop,
            width: initialCardWidth,
            height: cardHeight,
            backgroundColor: "#FFFFFF",
            borderRadius: 24 * s,
            opacity: leftCardOpacity,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            paddingTop: 60 * s,
            boxShadow: `0 10px 30px rgba(0,0,0,0.2)`,
            transition: "none",
          }}
        >
          <div
            style={{
              fontSize: 56 * s,
              fontWeight: 900,
              color: "#1A202C",
              letterSpacing: -1 * s,
              marginBottom: 40 * s,
            }}
          >
            {leftCardTitle}
          </div>

          <div style={{ position: "relative", width: "100%", flex: 1 }}>
            {/* Blinking Cursor */}
            <div
              style={{
                position: "absolute",
                left: 60 * s,
                top: 20 * s,
                width: 4 * s,
                height: 50 * s,
                backgroundColor: "#000",
                opacity: cursorBlink,
                transition: "none",
              }}
            />

            {/* Red X SVG */}
            <svg
              width={xAreaWidth}
              height={xAreaHeight}
              style={{
                position: "absolute",
                top: "50%",
                left: "50%",
                transform: "translate(-50%, -50%)",
                overflow: "visible",
                transition: "none",
              }}
            >
              {/* Path 1: Top-Left to Bottom-Right */}
              <path
                d={`M 0 0 L ${xAreaWidth} ${xAreaHeight}`}
                stroke="#FF4B4B"
                strokeWidth={20 * s}
                strokeLinecap="round"
                fill="none"
                strokeDasharray={pathLength}
                strokeDashoffset={interpolate(xDraw1Progress, [0, 1], [pathLength, 0])}
                style={{ transition: "none" }}
              />
              {/* Path 2: Top-Right to Bottom-Left */}
              <path
                d={`M ${xAreaWidth} 0 L 0 ${xAreaHeight}`}
                stroke="#FF4B4B"
                strokeWidth={20 * s}
                strokeLinecap="round"
                fill="none"
                strokeDasharray={pathLength}
                strokeDashoffset={interpolate(xDraw2Progress, [0, 1], [pathLength, 0])}
                style={{ transition: "none" }}
              />
            </svg>
          </div>
        </div>

        {/* RIGHT CARD (FORMULA TEMPLATE) */}
        <div
          style={{
            position: "absolute",
            left: currentRightCardX,
            top: cardTop,
            width: currentRightCardWidth,
            height: cardHeight,
            backgroundColor: "#F4FEE4",
            borderRadius: 24 * s,
            border: `${4 * s}px solid #C5F250`,
            boxShadow,
            display: "flex",
            flexDirection: "column",
            padding: 40 * s,
            transition: "none",
          }}
        >
          {/* Header Area */}
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              marginBottom: 30 * s,
            }}
          >
            <div
              style={{
                fontSize: 48 * s,
                fontWeight: 900,
                color: "#1A202C",
                letterSpacing: -1 * s,
                lineHeight: 1.1,
                textAlign: "center",
              }}
            >
              {rightCardTitle1}
              <br />
              {rightCardTitle2}
            </div>

            {/* Document Icon SVG */}
            <div style={{ marginTop: 30 * s }}>
              <svg width={160 * s} height={200 * s} viewBox="0 0 160 200">
                {/* Doc Base */}
                <path
                  d="M16 0 L112 0 L160 48 L160 184 A16 16 0 0 1 144 200 L16 200 A16 16 0 0 1 0 184 L0 16 A16 16 0 0 1 16 0 Z"
                  fill="none"
                  stroke="#9CCC3D"
                  strokeWidth={6}
                />
                {/* Fold Line */}
                <path
                  d="M112 0 L112 32 A16 16 0 0 0 128 48 L160 48"
                  fill="none"
                  stroke="#9CCC3D"
                  strokeWidth={6}
                  strokeLinecap="round"
                />
                {/* 'fx' Text */}
                <text
                  x="80"
                  y="90"
                  fontFamily={playfairFamily}
                  fontSize={64}
                  fontStyle="italic"
                  fontWeight="bold"
                  fill="#6A9E14"
                  textAnchor="middle"
                >
                  fx
                </text>
                {/* Abstract Code Lines */}
                <rect x="24" y="120" width="24" height="12" rx="6" fill="#88C222" />
                <rect x="56" y="120" width="64" height="12" rx="6" fill="#C5F250" />
                <rect x="24" y="144" width="24" height="12" rx="6" fill="#88C222" />
                <rect x="56" y="144" width="48" height="12" rx="6" fill="#C5F250" />
                <rect x="24" y="168" width="24" height="12" rx="6" fill="#88C222" />
                <rect x="56" y="168" width="56" height="12" rx="6" fill="#C5F250" />
              </svg>
            </div>
          </div>

          {/* List Items */}
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              gap: 12 * s,
              flex: 1,
              justifyContent: "flex-end",
            }}
          >
            {templateItems.map((item, index) => {
              const isResult = item.isResult;
              return (
                <div
                  key={index}
                  style={{
                    width: "100%",
                    backgroundColor: isResult ? "#E2FA90" : "transparent",
                    border: `${2 * s}px solid #C5F250`,
                    borderRadius: 16 * s,
                    padding: `${16 * s}px ${24 * s}px`,
                    display: "flex",
                    flexDirection: "column",
                    justifyContent: "center",
                    minHeight: 80 * s,
                  }}
                >
                  {!isResult && item.label && (
                    <div
                      style={{
                        fontSize: 18 * s,
                        fontWeight: 800,
                        color: "#5B9013",
                        marginBottom: 4 * s,
                        textTransform: "uppercase",
                      }}
                    >
                      {item.label}
                    </div>
                  )}
                  <div
                    style={{
                      fontSize: isResult ? 36 * s : 28 * s,
                      fontWeight: 800,
                      color: "#1A202C",
                      textAlign: isResult ? "center" : "left",
                    }}
                  >
                    {item.value}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default FormulaTemplate;